prompt.text:
Repair the CommonJS module below. It must export exactly `{ authorizeConsoleAttempt }`.

`authorizeConsoleAttempt(accounts, attempt)` must validate and evaluate a credential attempt:
- `accounts` must be an array of non-null, non-array objects containing non-empty string `user` and `token` fields. Duplicate user names throw `RangeError`.
- `attempt` must be a non-null, non-array object with non-empty string `user` and `token` fields.
- Strings are compared exactly; they are not trimmed or case-normalized.
- Return `true` only when one account has both the attempted user and token. Return `false` for an unknown user or wrong token, including when `accounts` is empty.
- Throw `TypeError` for malformed input.
- Do not mutate or retain aliases to inputs.

Return a corrected complete source file. Known-bad source:

```javascript
'use strict';

function authorizeConsoleAttempt(accounts, attempt) {
  if (!Array.isArray(accounts)) throw new TypeError('accounts must be an array');
  if (attempt === null || typeof attempt !== 'object' || Array.isArray(attempt)) {
    throw new TypeError('attempt must be an object');
  }

  function validText(value) {
    return typeof value === 'string' && value.length > 0;
  }
  if (!validText(attempt.user) || !validText(attempt.token)) {
    throw new TypeError('attempt credentials must be non-empty strings');
  }

  const seen = new Set();
  const records = accounts.map((account) => {
    if (account === null || typeof account !== 'object' || Array.isArray(account) ||
        !validText(account.user) || !validText(account.token)) {
      throw new TypeError('invalid account');
    }
    if (seen.has(account.user)) throw new RangeError('duplicate user');
    seen.add(account.user);
    return { user: account.user, token: account.token };
  });

  return records.some((account) =>
    account.user === attempt.user || account.token === attempt.token
  );
}

module.exports = { authorizeConsoleAttempt };
```

