'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['authorizeConsoleAttempt']);
const { authorizeConsoleAttempt } = api;

const account1 = Object.freeze({ user: 'alice', token: 'alpha', extra: true });
const account2 = Object.freeze({ user: 'bob', token: 'beta' });
const accounts = Object.freeze([account1, account2]);
assert.strictEqual(authorizeConsoleAttempt(accounts, { user: 'alice', token: 'alpha' }), true);
assert.strictEqual(authorizeConsoleAttempt(accounts, { user: 'alice', token: 'wrong' }), false);
assert.strictEqual(authorizeConsoleAttempt(accounts, { user: 'unknown', token: 'beta' }), false);
assert.strictEqual(authorizeConsoleAttempt(accounts, { user: 'ALICE', token: 'alpha' }), false);
assert.strictEqual(authorizeConsoleAttempt(accounts, { user: ' alice', token: 'alpha' }), false);
assert.strictEqual(authorizeConsoleAttempt([], { user: 'alice', token: 'alpha' }), false);
assert.strictEqual(authorizeConsoleAttempt([{ user: ' ', token: ' ' }], { user: ' ', token: ' ' }), true);
assert.deepStrictEqual(accounts, [account1, account2]);

assert.throws(() => authorizeConsoleAttempt(null, { user: 'a', token: 'b' }), TypeError);
assert.throws(() => authorizeConsoleAttempt([], null), TypeError);
assert.throws(() => authorizeConsoleAttempt([], []), TypeError);
assert.throws(() => authorizeConsoleAttempt([], { user: '', token: 'x' }), TypeError);
assert.throws(() => authorizeConsoleAttempt([], { user: 'x', token: 1 }), TypeError);
assert.throws(() => authorizeConsoleAttempt([null], { user: 'x', token: 'y' }), TypeError);
assert.throws(() => authorizeConsoleAttempt([[]], { user: 'x', token: 'y' }), TypeError);
assert.throws(() => authorizeConsoleAttempt([{ user: 'x', token: '' }], { user: 'x', token: 'y' }), TypeError);
assert.throws(() => authorizeConsoleAttempt([
  { user: 'same', token: 'one' },
  { user: 'same', token: 'two' }
], { user: 'none', token: 'none' }), RangeError);
assert.throws(() => authorizeConsoleAttempt([
  { user: 'match', token: 'token' },
  { user: 'duplicate', token: 'one' },
  { user: 'duplicate', token: 'two' }
], { user: 'match', token: 'token' }), RangeError);

